import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_counts_none_in_denominator():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": None}]) == 0.5
    assert monitor_flag_rate([]) == 0.0


def test_dedupe_keeps_last_occurrence_then_sorts():
    events = parse_transcript_log(["a,5,1", "c,3,0", "b,1,1", "a,3,0"])
    assert dedupe_transcripts(events) == [events[2], events[3], events[1]]


def test_log_skips_comments_and_blank_lines_and_strips_fields():
    assert parse_transcript_log(["", " \t", "  # comment", " a , 4 , 0 ", "b,2, "]) == [
        {"id": "a", "day": 4, "flagged": False},
        {"id": "b", "day": 2, "flagged": None},
    ]


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,0,extra", "a,no,0"])
def test_log_error_uses_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"line 3\b"):
        parse_transcript_log(["# skip", " ", bad_line])


def test_daily_counts_include_empty_days_and_ignore_outside_range():
    events = parse_transcript_log(["a,1,1", "b,3,1", "c,3,1", "d,5,1"])
    assert daily_flag_counts(events, 2, 4) == [0, 2, 0]
    assert daily_flag_counts(events, 4, 2) == []


def test_window_sizes():
    assert flags_in_window([4, 1, 2], 0) == 0
    assert flags_in_window([4, 1, 2], 2) == 3
    assert flags_in_window([4, 1, 2], 6) == 7


def test_summary_weights_transcripts_and_uses_calendar_days():
    groups = {"a": parse_transcript_log(["a,1,1"]), "b": parse_transcript_log(["b,4,0", "c,1,"]), "c": []}
    assert monitor_summary(groups, 2) == {"rate": 0.333, "recent": 0, "groups": 2}
    assert monitor_summary({"empty": []}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert pooled_flag_rate({}) == 0.0


def test_group_ordering_and_empty_groups():
    groups = {"z": [{"flagged": False}], "empty": [], "a": [{"flagged": None}], "b": [{"flagged": True}]}
    assert top_flagged_groups(groups, 5) == ["b", "a", "z"]
    assert top_flagged_groups(groups, 2) == ["b", "a"]
    assert list(flag_rate_by_group(groups).items()) == [("a", 0.0), ("b", 1.0), ("empty", None), ("z", 0.0)]


def test_streak_counts_only_consecutive_positive_days():
    assert longest_flag_streak([1, 0, 1, 2, -1, 1]) == 2
    assert longest_flag_streak([]) == 0
